@SSet.finite_of_epi.{u_1} : ∀ {X Y : SSet.{u_1}} [X.Finite]
  (f :
    @Quiver.Hom.{u_1, u_1 + 1} SSet.{u_1}
      (@CategoryTheory.CategoryStruct.toQuiver.{u_1, u_1 + 1} SSet.{u_1}
        (@CategoryTheory.Category.toCategoryStruct.{u_1, u_1 + 1} SSet.{u_1}
          (@CategoryTheory.Functor.category.{0, u_1, 0, u_1 + 1} (Opposite.{1} SimplexCategory)
            (@CategoryTheory.Category.opposite.{0, 0} SimplexCategory SimplexCategory.smallCategory) (Type u_1)
            CategoryTheory.types.{u_1})))
      X Y)
  [hf :
    @CategoryTheory.Epi.{u_1, u_1 + 1} SSet.{u_1}
      (@CategoryTheory.Functor.category.{0, u_1, 0, u_1 + 1} (Opposite.{1} SimplexCategory)
        (@CategoryTheory.Category.opposite.{0, 0} SimplexCategory SimplexCategory.smallCategory) (Type u_1)
        CategoryTheory.types.{u_1})
      X Y f],
  Y.Finite

SSet.finite_of_hasDimensionLT.{u_1} : ∀ (X : SSet.{u_1}) (d : Nat) [X.HasDimensionLT d],
  (∀ (i : Nat),
      @LT.lt.{0} Nat instLTNat i d →
        Finite.{u_1 + 1}
          (@Set.Elem.{u_1}
            (@CategoryTheory.Functor.obj.{0, u_1, 0, u_1 + 1} (Opposite.{1} SimplexCategory)
              (@CategoryTheory.Category.opposite.{0, 0} SimplexCategory SimplexCategory.smallCategory) (Type u_1)
              CategoryTheory.types.{u_1} X (@Opposite.op.{1} SimplexCategory { len := i }))
            (X.nonDegenerate i))) →
    X.Finite
